  text-decoration: none;
  letter-spacing: 1px;
  transition: color var(--transition);
}

.logo:hover,
.logo:focus {
  color: var(--primary);
  outline: none;
}

nav {
  /* for desktop, handled in ul */
}

.nav-list {
  display: flex;
  gap: 2.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-list a {
  color: var(--text);
  text-decoration: none;
  font-weight: 500;
  font-size: 1rem;
  transition: color var(--transition);
  position: relative;
  padding: 0.25em 0;
}

.nav-list a:after {
  content: '';
  display: block;
  height: 2px;
  width: 0;
  background: var(--primary);
  transition: width 0.2s;
  position: absolute;
  left: 0;
  bottom: 0;
}

.nav-list a:hover,
.nav-list a:focus {
  color: var(--primary);
  outline: none;
}

.nav-list a:hover:after,
.nav-list a:focus:after {
  width: 100%;
}

.nav-toggle {
